# Milaan - crash fix: type checking back on, samples out of the live deck
# Chalao:  powershell -ExecutionPolicy Bypass -File apply-crash-fix.ps1
# Kaam hone ke baad ye file khud ko delete kar degi.

$root = $PSScriptRoot
if (-not (Test-Path (Join-Path $root "frontend\package.json"))) {
  Write-Host "Ye file milaan folder ke andar rakho (jahan frontend aur backend hain)." -ForegroundColor Red
  exit 1
}
Set-Location $root
Write-Host "crash fix: type checking back on, samples out of the live deck apply ho raha hai..." -ForegroundColor Cyan

$removed = @(
  "frontend/src/features/social/screens/PeopleListScreen.tsx",
  "frontend/src/features/social/screens/RequestsScreen.tsx"
)
$d = 0
foreach ($f in $removed) { if (Test-Path $f) { Remove-Item $f -Force -Recurse; $d++ } }
if ($removed.Count) { Write-Host "  $d purani file hatai" }

$tmp = Join-Path $env:TEMP ("milaan-" + [guid]::NewGuid().ToString("N"))
New-Item -ItemType Directory -Path $tmp -Force | Out-Null
$zip = Join-Path $tmp "payload.zip"
$b64 = @"

"@
[IO.File]::WriteAllBytes($zip, [Convert]::FromBase64String($b64))
Expand-Archive -Path $zip -DestinationPath $tmp -Force
Remove-Item $zip -Force
$n = (Get-ChildItem $tmp -Recurse -File).Count
Copy-Item -Path (Join-Path $tmp "*") -Destination $root -Recurse -Force
Remove-Item $tmp -Recurse -Force
Write-Host "  $n file update ki"

Get-ChildItem frontend\src -Directory -Recurse | Sort-Object FullName -Descending |
  Where-Object { @(Get-ChildItem $_.FullName -Force).Count -eq 0 } | Remove-Item -Force

$found = Select-String -Path "frontend/src/app/MilaanApp.tsx" -Pattern "@ts-nocheck" -SimpleMatch -Quiet
$ok = -not $found
Write-Host ""
if ($ok) {
  Write-Host "crash fix: type checking back on, samples out of the live deck apply ho gaya. Ab frontend restart karo:" -ForegroundColor Green
  Write-Host "  cd frontend ; pnpm start"
  Remove-Item $MyInvocation.MyCommand.Path -Force
} else {
  Write-Host "Kuch gadbad hui - check fail hua. Mujhe batao." -ForegroundColor Red
}
